import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import { useAuth } from '../context/AuthContext';

export default function Doctors() {
  const [doctors, setDoctors] = useState([]);
  const [booking, setBooking] = useState({ doctorId: '', date: '', time: '' });
  const [msg, setMsg] = useState('');
  const { auth } = useAuth();
  const navigate = useNavigate();

  useEffect(() => { api.get('/doctors').then(r => setDoctors(r.data)); }, []);

  const book = async (doctorId) => {
    if (!booking.date || !booking.time) return setMsg('Pick date and time first');
    try {
      await api.post('/appointments', { doctor: doctorId, date: booking.date, time: booking.time });
      setMsg('Appointment booked!');
    } catch (err) {
      setMsg(err.response?.data?.message || 'Error');
    }
  };

  const openChat = (doctorId) => {
    const roomId = [auth.user.id, doctorId].sort().join('_');
    navigate(`/chat/${roomId}`);
  };

  return (
    <div className="mt-6">
      <h2 className="text-xl font-bold mb-4">Available Doctors</h2>
      {msg && <p className="text-green-600 mb-3 text-sm">{msg}</p>}
      <div className="mb-4 flex gap-3">
        <input type="date" className="input" value={booking.date}
          onChange={e => setBooking({ ...booking, date: e.target.value })} />
        <input type="time" className="input" value={booking.time}
          onChange={e => setBooking({ ...booking, time: e.target.value })} />
      </div>
      <div className="space-y-3">
        {doctors.map(doc => (
          <div key={doc._id} className="border rounded p-4 flex items-center justify-between">
            <div>
              <p className="font-semibold">{doc.name}</p>
              <p className="text-sm text-gray-500">{doc.specialization}</p>
              <p className="text-xs text-gray-400">{doc.availability}</p>
            </div>
            <div className="flex gap-2">
              <button onClick={() => book(doc._id)} className="btn text-sm">Book</button>
              <button onClick={() => openChat(doc._id)} className="btn-outline text-sm">Chat</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
